<script setup lang="ts">
import{nextTick,onBeforeUnmount,onMounted,ref}from'vue';import*as echarts from'echarts';import{api,type ApiResponse}from'@whaashop/shared';interface Dashboard{sales:number;orders:number;users:number;rating:number;todayOrders:number;publishedProducts:number;hotProducts:{name:string;sales:number}[];trend:{day:string;orders:number;sales:number}[];orderStatus:{status:string;value:number}[];categorySales:{name:string;value:number}[];userTrend:{day:string;users:number}[]}const data=ref<Dashboard>({sales:0,orders:0,users:0,rating:0,todayOrders:0,publishedProducts:0,hotProducts:[],trend:[],orderStatus:[],categorySales:[],userTrend:[]});const trendEl=ref<HTMLElement>(),statusEl=ref<HTMLElement>(),categoryEl=ref<HTMLElement>(),userEl=ref<HTMLElement>();const charts:echarts.ECharts[]=[];const statusLabels:Record<string,string>={PENDING_PAYMENT:'待支付',PAID:'待发货',SHIPPED:'已发货',COMPLETED:'已完成',CLOSED:'已关闭'},palette=['#409eff','#67c23a','#e6a23c','#f56c6c','#8e72d5','#31b6b0'];function init(el:HTMLElement){const chart=echarts.init(el);charts.push(chart);return chart}function resize(){charts.forEach(chart=>chart.resize())}onMounted(async()=>{data.value=(await api.get<ApiResponse<Dashboard>>('/admin/statistics/dashboard')).data.data;await nextTick();init(trendEl.value!).setOption({color:['#79bbff','#1d6fba'],tooltip:{trigger:'axis'},legend:{top:0,data:['订单量','销售额']},grid:{left:48,right:48,bottom:35,top:45},xAxis:{type:'category',data:data.value.trend.map(v=>v.day)},yAxis:[{type:'value',minInterval:1,name:'订单'},{type:'value',name:'销售额'}],series:[{name:'订单量',type:'bar',barMaxWidth:28,data:data.value.trend.map(v=>v.orders),itemStyle:{borderRadius:[6,6,0,0]}},{name:'销售额',type:'line',yAxisIndex:1,smooth:true,symbolSize:8,data:data.value.trend.map(v=>v.sales)}]});init(statusEl.value!).setOption({color:palette,tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',radius:['44%','70%'],center:['50%','45%'],padAngle:3,itemStyle:{borderRadius:6},label:{formatter:'{b}\n{d}%'},data:data.value.orderStatus.map(v=>({name:statusLabels[v.status]??v.status,value:v.value}))}]});init(categoryEl.value!).setOption({tooltip:{trigger:'axis',axisPointer:{type:'shadow'}},grid:{left:70,right:25,bottom:30,top:15},xAxis:{type:'value',minInterval:1},yAxis:{type:'category',data:[...data.value.categorySales].reverse().map(v=>v.name)},series:[{type:'bar',barMaxWidth:20,data:[...data.value.categorySales].reverse().map(v=>v.value),itemStyle:{borderRadius:[0,7,7,0],color:new echarts.graphic.LinearGradient(0,0,1,0,[{offset:0,color:'#79bbff'},{offset:1,color:'#1d6fba'}])}}]});init(userEl.value!).setOption({tooltip:{trigger:'axis'},grid:{left:45,right:20,bottom:35,top:20},xAxis:{type:'category',data:data.value.userTrend.map(v=>v.day)},yAxis:{type:'value',minInterval:1},series:[{type:'line',smooth:true,symbolSize:8,data:data.value.userTrend.map(v=>v.users),lineStyle:{width:3,color:'#67c23a'},itemStyle:{color:'#67c23a'},areaStyle:{color:new echarts.graphic.LinearGradient(0,0,0,1,[{offset:0,color:'#95d475aa'},{offset:1,color:'#f0f9eb22'}])}}]});window.addEventListener('resize',resize)});onBeforeUnmount(()=>{window.removeEventListener('resize',resize);charts.forEach(chart=>chart.dispose())});
</script>
<template><div class="dashboard-heading"><div><h2>经营数据看板</h2><p>商城核心经营指标与近 7 日数据趋势</p></div><span>数据实时更新</span></div><div class="cards dashboard-cards"><div class="card"><b>累计销售额</b><h2>¥ {{Number(data.sales).toFixed(2)}}</h2><small>已支付及已完成订单</small></div><div class="card"><b>订单总量</b><h2>{{data.orders}}</h2><small>今日新增 {{data.todayOrders}} 单</small></div><div class="card"><b>商城用户</b><h2>{{data.users}}</h2><small>累计普通用户</small></div><div class="card"><b>在售商品</b><h2>{{data.publishedProducts}}</h2><small>当前已上架商品</small></div><div class="card"><b>平均评分</b><h2>{{data.rating}}</h2><small>基于公开商品评价</small></div></div><div class="dashboard-main-grid"><div class="panel chart-panel wide"><div class="panel-title"><h3>近 7 日经营趋势</h3><small>订单量 / 销售额</small></div><div ref="trendEl" class="dashboard-chart"/></div><div class="panel chart-panel"><div class="panel-title"><h3>订单状态分布</h3><small>订单履约结构</small></div><div ref="statusEl" class="dashboard-chart"/></div><div class="panel chart-panel"><div class="panel-title"><h3>分类商品销量</h3><small>已上架商品累计销量</small></div><div ref="categoryEl" class="dashboard-chart"/></div><div class="panel chart-panel"><div class="panel-title"><h3>近 7 日新增用户</h3><small>用户增长变化</small></div><div ref="userEl" class="dashboard-chart"/></div></div><div class="panel dashboard-ranking"><div class="panel-title"><h3>热销商品排行</h3><small>按累计销量排序</small></div><div class="rank-grid"><div v-for="(p,i) in data.hotProducts" :key="p.name" class="rank-item"><b :class="{top:i<3}">{{i+1}}</b><span>{{p.name}}</span><strong>{{p.sales}} 件</strong><i><em :style="{width:`${Math.max(5,p.sales/(data.hotProducts[0]?.sales||1)*100)}%`}"/></i></div></div><el-empty v-if="!data.hotProducts.length" description="暂无销售数据"/></div></template>
